<template>
  <ForgeDialog :title="original ? 'Configure Tomcat website' : 'New Tomcat website'" description="Configure the Tomcat app base, context mappings, ports and TLS." eyebrow="WEBSITES / TOMCAT" wide @close="emit('close')">
    <div class="tomcat-editor"><div class="form-grid"><label>Hostname<input v-model.trim="item.name" placeholder="app.localhost" /></label><label>Comment<input v-model.trim="item.mark" placeholder="Optional note" /></label></div><label>App base directory<div class="path-row"><input v-model.trim="item.root" /><button class="action-button" @click="chooseRoot">Browse</button></div></label><div class="contexts"><div class="section-head"><b>Context mappings</b><button class="action-button" @click="addContext">Add context</button></div><div v-for="(context,index) in item.tomcat.contexts" :key="context.id" class="context-row"><input v-model.trim="context.path" placeholder="/" /><input v-model.trim="context.docBase" placeholder="Document base" /><button class="text-button" @click="item.tomcat.contexts.splice(index,1)">Remove</button></div><p v-if="!item.tomcat.contexts.length" class="empty-copy">No explicit contexts. Tomcat will use the app base.</p></div><div class="form-grid"><label>Tomcat port<input v-model.number="item.port.tomcat" type="number" min="1" max="65535" /></label><label>SSL port<input v-model.number="item.port.tomcat_ssl" type="number" min="1" max="65535" /></label></div><div class="switch-line"><span>Enable HTTPS</span><input v-model="item.useSSL" type="checkbox" /></div><template v-if="item.useSSL"><div class="switch-line"><span>Managed certificate</span><input v-model="item.autoSSL" type="checkbox" /></div><div v-if="!item.autoSSL" class="form-grid"><label>Certificate<input v-model.trim="item.ssl.cert" /></label><label>Private key<input v-model.trim="item.ssl.key" /></label></div></template><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p></div><template #footer><span class="website-help">Saving restarts Tomcat when it was running.</span><div class="detail-actions"><button class="action-button" @click="emit('close')">Cancel</button><button class="primary-button" :disabled="saving" @click="save">{{ saving ? 'Saving…' : 'Save website' }}</button></div></template>
  </ForgeDialog>
</template>
<script setup lang="ts">
import { reactive, ref } from 'vue'
import ForgeDialog from '../components/ForgeDialog.vue'
import { dialog } from '@/util/NodeFn'
import { uuid } from '@/util/Index'
import tomcatSiteController from '@/components/Host/Tomcat/TomcatSiteController'
import { cloneTomcatSiteHost, createTomcatSiteConfig } from '@/components/Host/Tomcat/site'
import type { WebsiteHost } from './types'
const props=defineProps<{original?:WebsiteHost}>(); const emit=defineEmits<{close:[]; saved:[]}>(); const item=reactive(cloneTomcatSiteHost(props.original ?? { tomcat:createTomcatSiteConfig(), type:'tomcat' })); const saving=ref(false); const error=ref('')
const chooseRoot=async()=>{const result=await dialog.showOpenDialog({properties:['openDirectory','createDirectory','showHiddenFiles']});if(!result.canceled&&result.filePaths[0])item.root=result.filePaths[0]}
const addContext=()=>item.tomcat.contexts.push({id:uuid(12),path:'/',docBase:item.root})
const save=async()=>{error.value='';if(!item.name||!item.root){error.value='Hostname and app base are required.';return}if(item.useSSL&&!item.autoSSL&&(!item.ssl.cert||!item.ssl.key)){error.value='Certificate and private key are required when managed TLS is disabled.';return} saving.value=true;try{const ok=await tomcatSiteController.save(item as any,props.original?'edit':'add',props.original as any);if(!ok){error.value='Tomcat website could not be saved.';return}emit('saved');emit('close')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
</script>
<style scoped>
.tomcat-editor{display:grid;gap:14px;font-size:12px}.tomcat-editor label{display:grid;gap:7px;color:var(--pqt-text-muted)}.tomcat-editor input{width:100%;padding:9px 10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.path-row{display:flex;gap:8px}.contexts{display:grid;gap:8px}.section-head,.switch-line{display:flex;align-items:center;justify-content:space-between;gap:10px}.context-row{display:grid;grid-template-columns:120px 1fr auto;gap:7px}.switch-line{padding:9px 0;color:var(--pqt-text-muted)}
</style>
